// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Set;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

class LmdbAdjacencyCoverageTest {

	@Test
	void additionalSelectedPredicatesAreUnsignedMergedWithoutLosingClassification() {
		IRI unresolved = SimpleValueFactory.getInstance().createIRI("urn:unresolved");
		LmdbAdjacencyCoverage original = LmdbAdjacencyCoverage.selected(new long[] { 10, Long.MIN_VALUE },
				Set.of(unresolved));

		LmdbAdjacencyCoverage merged = original.withAdditionalSelected(new long[] { 5, 10, 50, -1 });

		assertThat(merged.selectedRawPredicateIdsCopy()).containsExactly(5, 10, 50, Long.MIN_VALUE, -1);
		assertThat(merged.unresolvedConfiguredIris()).containsExactly(unresolved);
		assertThat(merged.covers(5)).isTrue();
		assertThat(merged.covers(-1)).isTrue();
		assertThat(original.covers(5)).isFalse();
	}

	@Test
	void fullCoverageRemainsCanonicalWhenAdditionalPredicatesArrive() {
		LmdbAdjacencyCoverage full = LmdbAdjacencyCoverage.full();

		assertThat(full.withAdditionalSelected(new long[] { 1, 2 })).isSameAs(full);
	}
}
